import { gradeLevelForClass, isSupportedClassCode } from '../public-quiz-data.ts';
import type { DataConfig } from './config.ts';
import { RequestInputError } from './http.ts';
import { supabaseRpc } from './supabase.ts';

export type RosterRow = { classCode: string; seatNumber: number; pin: string | null };
export type RosterEntry = { classCode: string; seatNumber: number; hasPin: boolean };

const MAX_ROWS = 500;

/**
 * Parses pasted lines of `班級,座號[,PIN]` (comma, tab or spaces). In PIN mode a
 * blank PIN is generated by the server and shown to the teacher once.
 */
export function parseRoster(text: string, loginMode: DataConfig['loginMode']): RosterRow[] {
  const rows: RosterRow[] = [];
  const seen = new Set<string>();
  const lines = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  if (lines.length > MAX_ROWS) throw new RequestInputError(`一次最多匯入 ${MAX_ROWS} 位學生。`);
  lines.forEach((line, index) => {
    const [classCode = '', seat = '', pin = '', ...rest] = line.split(/[,\t ]+/);
    if (index === 0 && !/^\d+$/.test(seat)) return; // header row
    const where = `第 ${index + 1} 行`;
    if (rest.length) throw new RequestInputError(`${where}：欄位太多，格式是「班級,座號,PIN」。`);
    if (!isSupportedClassCode(classCode)) throw new RequestInputError(`${where}：班級 ${classCode} 不在網站的班級設定（SCHOOL_CLASSES）裡。`);
    const seatNumber = Number(seat);
    if (!Number.isInteger(seatNumber) || seatNumber < 1 || seatNumber > 99) throw new RequestInputError(`${where}：座號需為 1–99。`);
    if (pin && !/^\d{6}$/.test(pin)) throw new RequestInputError(`${where}：PIN 需為六位數字。`);
    const key = `${classCode}/${seatNumber}`;
    if (seen.has(key)) throw new RequestInputError(`${where}：${key} 重複。`);
    seen.add(key);
    rows.push({ classCode, seatNumber, pin: loginMode === 'pin' ? pin || randomPin() : null });
  });
  if (!rows.length) throw new RequestInputError('請貼上至少一位學生。');
  return rows;
}

export async function importRoster(
  config: DataConfig,
  rows: RosterRow[],
  actor: string,
  fetcher: typeof fetch = fetch,
): Promise<RosterRow[]> {
  for (const row of rows) {
    await supabaseRpc(config, 'upsert_student_enrollment', {
      p_school_year: config.schoolYear,
      p_class_code: row.classCode,
      p_grade_level: gradeLevelForClass(row.classCode),
      p_seat_number: row.seatNumber,
      p_pin: row.pin,
    }, fetcher);
  }
  // The audit trail records who changed which seats, never the PINs.
  await rest(config, 'translation_audit_log', fetcher, [{
    actor_type: 'teacher', actor_id: actor, action: 'import-roster',
    entity_type: 'roster', entity_id: config.schoolYear,
    after_data: { seats: rows.map((row) => `${row.classCode}/${row.seatNumber}`), pinMode: config.loginMode === 'pin' },
  }]);
  return rows;
}

export async function loadRoster(config: DataConfig, fetcher: typeof fetch = fetch): Promise<RosterEntry[]> {
  const rows = await rest<Array<{ class_code: string; seat_number: number; pin_hash: string | null }>>(config,
    `enrollments?select=class_code,seat_number,pin_hash&school_year=eq.${encodeURIComponent(config.schoolYear)}` +
    '&active=is.true&order=class_code.asc,seat_number.asc&limit=2000', fetcher);
  return rows.map((row) => ({ classCode: row.class_code, seatNumber: row.seat_number, hasPin: Boolean(row.pin_hash) }));
}

function randomPin(): string {
  const value = crypto.getRandomValues(new Uint32Array(1))[0] % 1_000_000;
  return String(value).padStart(6, '0');
}

async function rest<T>(config: DataConfig, path: string, fetcher: typeof fetch, body?: unknown): Promise<T> {
  const response = await fetcher(`${config.supabaseUrl}/rest/v1/${path}`, {
    method: body === undefined ? 'GET' : 'POST',
    headers: {
      apikey: config.supabaseSecretKey,
      authorization: `Bearer ${config.supabaseSecretKey}`,
      'content-type': 'application/json',
      prefer: 'return=minimal',
    },
    body: body === undefined ? undefined : JSON.stringify(body),
    cache: 'no-store',
    signal: AbortSignal.timeout(10_000),
  });
  if (!response.ok) throw new Error(`Roster request failed: ${response.status}`);
  return (body === undefined ? await response.json() : null) as T;
}
